package org.humanjourney.core.geography;
import java.util.*;
import com.google.gson.*;
import org.humanjourney.core.mapfeature.FeatureGeometry;
import org.humanjourney.core.water.WaterGeography.Point;
/** Geography budgets over the same immutable topology/containment primitives as water Map Features. */
public final class GeographyGeometry {
 public static final int MAX_VERTICES=4096,MAX_RINGS=128,CATALOG_VERTICES=1179648,CATALOG_RINGS=65536;
 public static FeatureGeometry check(FeatureGeometry g){if(g.kind()==FeatureGeometry.Kind.POLYLINE||g.vertexCount()>MAX_VERTICES||g.ringCount()>MAX_RINGS)throw new IllegalArgumentException("geography geometry exceeds4096vertices/128rings or is not areal");return g;}
 public static void catalog(Collection<FeatureGeometry> shapes){long vertices=0,rings=0;for(var g:shapes){check(g);vertices+=g.vertexCount();rings+=g.ringCount();if(vertices>CATALOG_VERTICES||rings>CATALOG_RINGS)throw new IllegalArgumentException("aggregate geography geometry budget exceeded: vertices="+vertices+" rings="+rings);}}
 private static void keys(JsonObject o,String... allowed){var set=Set.of(allowed);for(String k:o.keySet())if(!set.contains(k))throw new IllegalArgumentException("unknown geography geometry field: "+k);}
 public static List<Point> points(JsonElement e,int min,int max){if(e==null||!e.isJsonArray()||e.getAsJsonArray().size()<min||e.getAsJsonArray().size()>max)throw new IllegalArgumentException("invalid geography point count");var out=new ArrayList<Point>();for(var v:e.getAsJsonArray()){if(!v.isJsonArray()||v.getAsJsonArray().size()!=2)throw new IllegalArgumentException("point must be[X,Z]");var a=v.getAsJsonArray();for(var n:a)if(!n.isJsonPrimitive()||!n.getAsJsonPrimitive().isNumber())throw new IllegalArgumentException("point must be numeric");out.add(new Point(a.get(0).getAsDouble(),a.get(1).getAsDouble()));}return out;}
 private static final class Budget{int rings,vertices;FeatureGeometry.Ring ring(JsonElement e,String context){try{var p=points(e,3,MAX_VERTICES);vertices+=p.size();if(++rings>MAX_RINGS||vertices>MAX_VERTICES)throw new IllegalArgumentException("geography exceeds4096vertices/128rings");return new FeatureGeometry.Ring(p);}catch(RuntimeException error){throw new IllegalArgumentException(context+": "+error.getMessage(),error);}}}
 private static FeatureGeometry.Part part(JsonElement input,Budget budget,String context){try{if(input==null||!input.isJsonObject())throw new IllegalArgumentException("part must be object");var o=input.getAsJsonObject();keys(o,"outer","holes");var outer=budget.ring(o.get("outer"),context+" outer");var holes=new ArrayList<FeatureGeometry.Ring>();if(o.has("holes")){if(!o.get("holes").isJsonArray()||o.getAsJsonArray("holes").size()>127)throw new IllegalArgumentException("invalid hole count");int i=0;for(var h:o.getAsJsonArray("holes"))holes.add(budget.ring(h,context+" hole["+i+++"]"));}return new FeatureGeometry.Part(outer,holes);}catch(RuntimeException error){throw new IllegalArgumentException(context+": "+error.getMessage(),error);}}
 public static FeatureGeometry parse(JsonElement input,String context){if(input==null||!input.isJsonObject())throw new IllegalArgumentException(context+": geometry must be object");var o=input.getAsJsonObject();if(!o.has("type")||!o.get("type").isJsonPrimitive()||!o.getAsJsonPrimitive("type").isString())throw new IllegalArgumentException(context+": geometry type required");var budget=new Budget();return switch(o.get("type").getAsString()){
  case "polygon"->{keys(o,"type","outer","holes");var body=o.deepCopy();body.remove("type");yield check(FeatureGeometry.polygon(part(body,budget,context+" polygon")));}
  case "multipolygon"->{keys(o,"type","polygons");if(!o.has("polygons")||!o.get("polygons").isJsonArray()||o.getAsJsonArray("polygons").isEmpty()||o.getAsJsonArray("polygons").size()>128)throw new IllegalArgumentException(context+": invalid polygon part count");var parts=new ArrayList<FeatureGeometry.Part>();int i=0;for(var p:o.getAsJsonArray("polygons"))parts.add(part(p,budget,context+" component["+i+++"]"));yield check(FeatureGeometry.multipolygon(parts));}
  default->throw new IllegalArgumentException(context+": geography supports polygon/multipolygon only");};}
 private GeographyGeometry(){}
}
